/* CSS PART 1 OF 3 */

/* DESIGN TOKENS */
:root {
  color-scheme: light;
  --ink: #202a30;
  --ink-soft: #536168;
  --paper: #f7f6f2;
  --white: #ffffff;
  --navy: #243c49;
  --navy-deep: #192d37;
  --accent: #bd7448;
  --accent-dark: #995a36;
  --line: #deded7;
  --muted: #eeede7;
  --success: #426b57;

  --font-heading: "Barlow Condensed", "Arial Narrow", sans-serif;
  --font-body: "DM Sans", "Segoe UI", sans-serif;

  --container: 1160px;
  --gutter: clamp(20px, 5vw, 76px);
  --section-space: clamp(76px, 10vw, 132px);

  --radius-sm: 4px;
  --radius-md: 9px;
  --radius-lg: 16px;

  --shadow: 0 16px 45px rgba(25, 45, 55, 0.12);
  --transition: 180ms ease;
}

/* RESET */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img,
picture,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  color: inherit;
}

::selection {
  background: var(--accent);
  color: var(--white);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
h4,
p {
  margin-top: 0;
}

h1,
h2,
h3,
h4 {
  color: var(--navy-deep);
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.04;
  letter-spacing: -0.025em;
}

h1 {
  font-size: clamp(3.3rem, 7.5vw, 6.4rem);
}

h2 {
  font-size: clamp(2.5rem, 5vw, 4.25rem);
}

h3 {
  font-size: clamp(1.65rem, 2.8vw, 2.25rem);
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--accent-dark);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: var(--accent);
  content: "";
}

.lead {
  max-width: 620px;
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.8;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--accent-dark);
  font-weight: 750;
  transition: color var(--transition);
}

.text-link:hover {
  color: var(--navy-deep);
}

/* PAGE LAYOUT */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section-heading {
  max-width: 740px;
  margin-bottom: 48px;
}

.section-heading p {
  max-width: 610px;
  margin-bottom: 0;
  font-size: 1.05rem;
}

.page-shell {
  overflow: clip;
  width: 100%;
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 42, 48, 0.09);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  width: min(1320px, calc(100% - var(--gutter) * 1.4));
  min-height: 94px;
  margin-inline: auto;
}

.brand {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  gap: 13px;
}

.brand img {
  width: 58px;
  height: 58px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.12;
}

.brand-name {
  color: var(--navy-deep);
  font-family: var(--font-heading);
  font-size: 1.42rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.brand-caption {
  margin-top: 5px;
  color: var(--ink-soft);
  font-size: 0.62rem;
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(17px, 2.5vw, 34px);
}

.primary-nav a {
  position: relative;
  padding-block: 12px;
  color: var(--ink);
  font-size: 0.85rem;
  font-weight: 700;
  transition: color var(--transition);
}

.primary-nav a::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 2px;
  background: var(--accent);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.primary-nav a:hover {
  color: var(--accent-dark);
}

.primary-nav a:hover::after,
.primary-nav a:focus-visible::after {
  transform: scaleX(1);
}

.header-contact {
  display: flex;
  align-items: center;
  gap: 15px;
}

.header-phone {
  color: var(--navy);
  font-size: 0.88rem;
  font-weight: 800;
  white-space: nowrap;
}

/* REUSABLE BUTTONS */
.btn {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: var(--white);
  cursor: pointer;
  font-size: 0.88rem;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
  transition:
    background var(--transition),
    border-color var(--transition),
    color var(--transition),
    transform var(--transition);
}

.btn:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
}

.btn:active {
  transform: translateY(0);
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
}

.btn-secondary {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.btn-secondary:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--navy-deep);
}

.btn-dark {
  background: var(--navy);
  color: var(--white);
}

.btn-dark:hover {
  background: var(--navy-deep);
}

.btn-light {
  border-color: var(--line);
  background: var(--white);
  color: var(--navy);
}

.btn-light:hover {
  border-color: var(--navy);
  background: var(--navy);
  color: var(--white);
}

/* HERO */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - 94px));
  align-items: center;
  isolation: isolate;
  overflow: hidden;
  background: var(--navy-deep);
  color: var(--white);
}

.hero-media {
  position: absolute;
  z-index: -2;
  inset: 0;
}

.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(19, 36, 45, 0.94) 0%,
    rgba(19, 36, 45, 0.84) 43%,
    rgba(19, 36, 45, 0.34) 76%,
    rgba(19, 36, 45, 0.12) 100%
  );
  content: "";
}

.hero-inner {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
  padding-block: clamp(85px, 11vw, 150px);
}

.hero-content {
  max-width: 760px;
}

.hero .eyebrow {
  color: #e5b18d;
}

.hero h1 {
  max-width: 780px;
  margin-bottom: 25px;
  color: var(--white);
  font-size: clamp(3.6rem, 8.5vw, 7.2rem);
}

.hero-description {
  max-width: 590px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.87);
  font-size: clamp(1.05rem, 1.6vw, 1.22rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 38px;
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.82rem;
  font-weight: 650;
  letter-spacing: 0.035em;
}

.hero-note::before {
  width: 34px;
  height: 1px;
  background: var(--accent);
  content: "";
}
