/* CSS PART 2 OF 3 */

/* COMPANY INTRODUCTION */
.intro-section {
  padding-block: var(--section-space);
  background: var(--paper);
}

.intro-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: clamp(45px, 8vw, 110px);
}

.intro-visual {
  position: relative;
  min-height: 480px;
}

.intro-visual img {
  width: 100%;
  height: 480px;
  border-radius: var(--radius-md);
  object-fit: cover;
}

.intro-accent {
  position: absolute;
  right: -22px;
  bottom: -22px;
  width: 42%;
  height: 42%;
  border-right: 5px solid var(--accent);
  border-bottom: 5px solid var(--accent);
  pointer-events: none;
}

.intro-copy {
  max-width: 570px;
}

.intro-copy h2 {
  margin-bottom: 25px;
}

.intro-copy p {
  margin-bottom: 18px;
}

.intro-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 32px;
  margin-top: 34px;
  padding-top: 27px;
  border-top: 1px solid var(--line);
}

.intro-fact {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.intro-fact strong {
  color: var(--navy);
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1;
}

.intro-fact span {
  color: var(--ink-soft);
  font-size: 0.77rem;
  font-weight: 700;
}

/* SERVICE OVERVIEW */
.services-section {
  padding-block: var(--section-space);
  background: var(--white);
}

.services-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 48px;
}

.services-heading .section-heading {
  margin-bottom: 0;
}

.services-list {
  border-top: 1px solid var(--line);
}

.service-item {
  display: grid;
  grid-template-columns: 75px 1fr auto;
  align-items: center;
  gap: 30px;
  padding: 31px 10px;
  border-bottom: 1px solid var(--line);
  transition:
    padding var(--transition),
    background var(--transition);
}

.service-item:hover {
  padding-inline: 20px;
  background: var(--paper);
}

.service-number {
  color: var(--accent);
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
}

.service-copy h3 {
  margin-bottom: 8px;
}

.service-copy p {
  max-width: 620px;
  margin-bottom: 0;
  font-size: 0.94rem;
}

.service-arrow {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--navy);
  font-size: 1.2rem;
  transition: all var(--transition);
}

.service-item:hover .service-arrow {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--white);
}

/* PROJECT GALLERY */
.projects-section {
  padding-block: var(--section-space);
  background: var(--navy-deep);
}

.projects-section h2 {
  color: var(--white);
}

.projects-section .section-heading p {
  color: rgba(255, 255, 255, 0.72);
}

.projects-section .eyebrow {
  color: #e5b18d;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  grid-template-rows: 290px 290px;
  gap: 18px;
}

.project-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border-radius: var(--radius-md);
  background: #344a53;
  isolation: isolate;
}

.project-card:first-child {
  grid-row: span 2;
}

.project-card img {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project-card:hover img {
  transform: scale(1.045);
}

.project-card::after {
  position: absolute;
  z-index: -1;
  inset: 35% 0 0;
  background: linear-gradient(
    0deg,
    rgba(17, 31, 38, 0.9),
    rgba(17, 31, 38, 0)
  );
  content: "";
}

.project-caption {
  position: absolute;
  right: 25px;
  bottom: 24px;
  left: 25px;
  color: var(--white);
}

.project-caption span {
  display: block;
  margin-bottom: 7px;
  color: #e9b58f;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.project-caption h3 {
  margin-bottom: 0;
  color: var(--white);
  font-size: clamp(1.5rem, 2.6vw, 2.1rem);
}

/* ROOF ATTENTION GUIDE */
.roof-guide {
  padding-block: var(--section-space);
  background: var(--muted);
}

.roof-guide-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: clamp(45px, 8vw, 100px);
}

.roof-guide-intro {
  position: sticky;
  top: 35px;
}

.roof-guide-intro h2 {
  margin-bottom: 22px;
}

.roof-guide-intro p {
  margin-bottom: 26px;
}

.roof-signs {
  border-top: 1px solid #d6d4cb;
}

.roof-sign {
  display: grid;
  grid-template-columns: 45px 1fr;
  gap: 19px;
  padding: 25px 0;
  border-bottom: 1px solid #d6d4cb;
}

.roof-sign-number {
  color: var(--accent-dark);
  font-family: var(--font-heading);
  font-size: 1.8rem;
  font-weight: 800;
}

.roof-sign h3 {
  margin-bottom: 7px;
  font-size: 1.5rem;
}

.roof-sign p {
  margin-bottom: 0;
  font-size: 0.94rem;
}

/* COLORADO ROOFING PROCESS */
.process-section {
  padding-block: var(--section-space);
  background: var(--paper);
}

.process-heading {
  max-width: 760px;
  margin-bottom: 55px;
}

.process-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-top: 2px solid var(--navy);
}

.process-step {
  position: relative;
  padding: 35px 24px 20px 0;
}

.process-step:not(:last-child) {
  margin-right: 24px;
  border-right: 1px solid var(--line);
}

.process-step-number {
  display: inline-block;
  margin-bottom: 26px;
  color: var(--accent);
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 800;
  line-height: 1;
}

.process-step h3 {
  margin-bottom: 12px;
  font-size: 1.55rem;
}

.process-step p {
  margin-bottom: 0;
  font-size: 0.91rem;
  line-height: 1.75;
}

/* FULL-WIDTH CONVERSION STRIP */
.midpage-cta {
  position: relative;
  overflow: hidden;
  padding-block: 65px;
  background: var(--accent);
  color: var(--white);
}

.midpage-cta-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
}

.midpage-cta h2 {
  max-width: 650px;
  margin-bottom: 10px;
  color: var(--white);
  font-size: clamp(2.1rem, 4vw, 3.5rem);
}

.midpage-cta p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.9);
}

.midpage-cta .btn {
  flex-shrink: 0;
  border-color: var(--white);
  background: var(--white);
  color: var(--navy-deep);
}

.midpage-cta .btn:hover {
  border-color: var(--navy-deep);
  background: var(--navy-deep);
  color: var(--white);
}
```

