/* CSS PART 3 OF 3 */

/* CONTACT AND CONVERSION */
.contact-section {
  padding-block: var(--section-space);
  background: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: clamp(45px, 8vw, 105px);
  align-items: start;
}

.contact-intro h2 {
  margin-bottom: 24px;
}

.contact-intro > p {
  max-width: 470px;
}

.contact-methods {
  display: grid;
  gap: 18px;
  margin-top: 35px;
}

.contact-method {
  display: flex;
  align-items: center;
  gap: 16px;
}

.contact-method-icon {
  display: grid;
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  place-items: center;
  border-radius: var(--radius-sm);
  background: var(--muted);
  color: var(--accent-dark);
  font-size: 1.2rem;
}

.contact-method-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.5;
}

.contact-method-copy span {
  color: var(--ink-soft);
  font-size: 0.76rem;
}

.contact-method-copy a {
  color: var(--navy);
  font-weight: 800;
}

.contact-form-wrap {
  padding: clamp(25px, 4vw, 46px);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--paper);
  box-shadow: var(--shadow);
}

.contact-form-wrap h3 {
  margin-bottom: 8px;
}

.contact-form-wrap > p {
  margin-bottom: 27px;
  font-size: 0.9rem;
}

.contact-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.form-field.full-width {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--navy);
  font-size: 0.82rem;
  font-weight: 750;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid #d6d7d1;
  border-radius: var(--radius-sm);
  background: var(--white);
  color: var(--ink);
  outline: none;
  transition:
    border-color var(--transition),
    box-shadow var(--transition);
}

.form-field textarea {
  min-height: 135px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #828b8e;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(189, 116, 72, 0.15);
}

.contact-form .btn {
  grid-column: 1 / -1;
  justify-self: start;
}

.form-note {
  grid-column: 1 / -1;
  margin: -5px 0 0;
  color: var(--ink-soft);
  font-size: 0.76rem;
}

/* FOOTER */
.site-footer {
  padding-top: 65px;
  background: var(--navy-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 48px;
}

.footer-brand {
  max-width: 380px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-caption {
  color: rgba(255, 255, 255, 0.65);
}

.footer-brand p {
  margin-top: 20px;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 55px;
}

.footer-column {
  display: flex;
  flex-direction: column;
  gap: 11px;
}

.footer-column h3 {
  margin-bottom: 9px;
  color: var(--white);
  font-size: 1.25rem;
}

.footer-column a {
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.86rem;
  transition: color var(--transition);
}

.footer-column a:hover {
  color: #e9b58f;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-block: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.17);
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.77rem;
}

/* RESPONSIVE: TABLET */
@media (max-width: 1050px) {
  .header-inner {
    flex-wrap: wrap;
    gap: 14px;
    padding-block: 15px;
  }

  .primary-nav {
    order: 3;
    width: 100%;
    justify-content: flex-start;
    gap: 27px;
    overflow-x: auto;
  }

  .header-contact {
