  .brand-caption {
    font-size: 0.56rem;
  }

  .header-contact {
    gap: 0;
  }

  .header-phone {
    font-size: 0.8rem;
  }

  .header-contact .btn {
    display: none;
  }

  .primary-nav {
    gap: 23px;
    padding-bottom: 3px;
  }

  .primary-nav a {
    flex-shrink: 0;
    font-size: 0.8rem;
  }

  .hero {
    min-height: 650px;
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(19, 36, 45, 0.92),
      rgba(19, 36, 45, 0.72)
    );
