/* RESPONSIVE: SMALL PHONES */
@media (max-width: 480px) {
  :root {
    --gutter: 19px;
    --section-space: 64px;
  }

  body {
    font-size: 15px;
  }

  .brand {
    gap: 8px;
  }

  .brand img {
    width: 39px;
    height: 39px;
  }

  .brand-name {
    font-size: 1.08rem;
  }

  .brand-caption {
    font-size: 0.5rem;
  }

  .header-phone {
    font-size: 0.73rem;
  }

  .primary-nav {
    gap: 19px;
  }

  .hero {
    min-height: 610px;
  }

  .hero h1 {
    font-size: clamp(3.1rem, 15vw, 4.4rem);
  }

  .hero-note {
    align-items: flex-start;
    font-size: 0.76rem;
  }

  .btn {
    min-height: 51px;
    padding-inline: 18px;
  }

